// Generated by scripts/sync-film.mjs from motion-film/src/utils/geometry.ts. Edit it there, then run `npm run sync:film`.
import { random } from "remotion";

export type Pt = [number, number];

const f = (n: number) => n.toFixed(2);

/** Smooth closed path through points (Catmull-Rom → cubic bezier). */
export const smoothClosedPath = (pts: Pt[], tension = 1): string => {
  const n = pts.length;
  let d = `M${f(pts[0][0])} ${f(pts[0][1])}`;
  for (let i = 0; i < n; i++) {
    const p0 = pts[(i - 1 + n) % n];
    const p1 = pts[i];
    const p2 = pts[(i + 1) % n];
    const p3 = pts[(i + 2) % n];
    const c1: Pt = [p1[0] + ((p2[0] - p0[0]) / 6) * tension, p1[1] + ((p2[1] - p0[1]) / 6) * tension];
    const c2: Pt = [p2[0] - ((p3[0] - p1[0]) / 6) * tension, p2[1] - ((p3[1] - p1[1]) / 6) * tension];
    d += ` C${f(c1[0])} ${f(c1[1])} ${f(c2[0])} ${f(c2[1])} ${f(p2[0])} ${f(p2[1])}`;
  }
  return `${d}Z`;
};

/** Organic blob (wax, petals, clouds) with low-frequency lumps plus fine jitter. */
export const blobPath = (
  cx: number,
  cy: number,
  r: number,
  variance: number,
  seed: string,
  n = 40,
): string => {
  const ph1 = random(`${seed}-p1`) * Math.PI * 2;
  const ph2 = random(`${seed}-p2`) * Math.PI * 2;
  const pts: Pt[] = [];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    const lump = 0.6 * Math.sin(a * 3 + ph1) + 0.4 * Math.sin(a * 7 + ph2);
    const jitter = (random(`${seed}-${i}`) - 0.5) * 0.5;
    const rr = r * (1 + variance * (lump + jitter));
    pts.push([cx + Math.cos(a) * rr, cy + Math.sin(a) * rr]);
  }
  return smoothClosedPath(pts);
};

export const cubicPoint = (p0: Pt, p1: Pt, p2: Pt, p3: Pt, t: number): Pt => {
  const u = 1 - t;
  return [
    u * u * u * p0[0] + 3 * u * u * t * p1[0] + 3 * u * t * t * p2[0] + t * t * t * p3[0],
    u * u * u * p0[1] + 3 * u * u * t * p1[1] + 3 * u * t * t * p2[1] + t * t * t * p3[1],
  ];
};

/** Joins points with small arcs — the scalloped "cusps" of a Mughal arch. */
export const cuspedPath = (pts: Pt[], sweep: 0 | 1, radiusFactor = 0.62): string => {
  let d = `M${f(pts[0][0])} ${f(pts[0][1])}`;
  for (let i = 1; i < pts.length; i++) {
    const [x0, y0] = pts[i - 1];
    const [x1, y1] = pts[i];
    const r = Math.hypot(x1 - x0, y1 - y0) * radiusFactor;
    d += ` A${f(r)} ${f(r)} 0 0 ${sweep} ${f(x1)} ${f(y1)}`;
  }
  return d;
};

export const polar = (cx: number, cy: number, r: number, deg: number): Pt => {
  const a = (deg * Math.PI) / 180;
  return [cx + Math.cos(a) * r, cy + Math.sin(a) * r];
};
